mapper.select:
SELECT ast06_company_id AS company_id, ast06_amt AS amt, ast06_for_amt AS for_amt
  FROM ast06_tr
 WHERE ast06_tr_id = #{trId}
   AND ast06_company_id = #{companyId}

SELECT ast07_settle_id AS settle_id, ast07_person_id AS person_id, ast07_tr_cd AS tr_code, ast07_settle_date AS settle_date
  FROM ast07_settle
       LEFT OUTER JOIN pay50_expense ON pay50_expense_id = ast07_expense_id
       LEFT OUTER JOIN ast06_tr      ON ast06_tr_id      = ast07_tr_id
 WHERE ast07_settle_id = #{settleId}
   AND COALESCE(pay50_company_id, ast06_company_id) = #{companyId}
